/**
 * RiveFile - Main class for generating .riv files
 */
import { BinaryWriter } from './binary-writer.js';
import { RIVE_FINGERPRINT, MAJOR_VERSION, MINOR_VERSION, FieldType, PropertyFieldType, ObjectType, PropertyKey, } from './core-types.js';
/**
 * RiveFile builder
 *
 * Builds a .riv file from objects and properties.
 * Handles the complex parentId encoding that Rive uses.
 */
export class RiveFile {
    objects = [];
    // Track first child position for each parent (for sibling parentId calculation)
    firstChildIndex = new Map();
    constructor() {
        // Always start with a Backboard
        this.addObject(ObjectType.Backboard, []);
    }
    /**
     * Add an object to the file
     * @returns The object's ID (index in file)
     */
    addObject(type, properties, absoluteParentId) {
        const id = this.objects.length;
        this.objects.push({ type, properties, absoluteParentId });
        // Track first child for this parent (used for sibling parentId calculation)
        if (absoluteParentId !== undefined && !this.firstChildIndex.has(absoluteParentId)) {
            this.firstChildIndex.set(absoluteParentId, id);
        }
        return id;
    }
    /**
     * Add an Artboard
     */
    addArtboard(options) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Artboard' },
            // Note: parentId defaults to 0 (Backboard), don't set explicitly
            { key: PropertyKey.width, value: options.width },
            { key: PropertyKey.height, value: options.height },
        ];
        if (options.originX !== undefined) {
            properties.push({ key: PropertyKey.originX, value: options.originX });
        }
        if (options.originY !== undefined) {
            properties.push({ key: PropertyKey.originY, value: options.originY });
        }
        return this.addObject(ObjectType.Artboard, properties);
    }
    /**
     * Add a Shape container (parent for paths and paints)
     */
    addShape(parentId, options = {}) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Shape' },
        ];
        if (options.x !== undefined) {
            properties.push({ key: PropertyKey.x, value: options.x });
        }
        if (options.y !== undefined) {
            properties.push({ key: PropertyKey.y, value: options.y });
        }
        return this.addObject(ObjectType.Shape, properties, parentId);
    }
    /**
     * Add an Ellipse path
     */
    addEllipse(parentId, options) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Ellipse' },
            { key: PropertyKey.pathWidth, value: options.width },
            { key: PropertyKey.pathHeight, value: options.height },
        ];
        if (options.x !== undefined) {
            properties.push({ key: PropertyKey.x, value: options.x });
        }
        if (options.y !== undefined) {
            properties.push({ key: PropertyKey.y, value: options.y });
        }
        return this.addObject(ObjectType.Ellipse, properties, parentId);
    }
    /**
     * Add a Rectangle path
     */
    addRectangle(parentId, options) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Rectangle' },
            { key: PropertyKey.pathWidth, value: options.width },
            { key: PropertyKey.pathHeight, value: options.height },
        ];
        if (options.x !== undefined) {
            properties.push({ key: PropertyKey.x, value: options.x });
        }
        if (options.y !== undefined) {
            properties.push({ key: PropertyKey.y, value: options.y });
        }
        if (options.cornerRadius !== undefined) {
            properties.push({ key: PropertyKey.cornerRadiusTL, value: options.cornerRadius });
            properties.push({ key: PropertyKey.cornerRadiusTR, value: options.cornerRadius });
            properties.push({ key: PropertyKey.cornerRadiusBL, value: options.cornerRadius });
            properties.push({ key: PropertyKey.cornerRadiusBR, value: options.cornerRadius });
        }
        return this.addObject(ObjectType.Rectangle, properties, parentId);
    }
    /**
     * Add a Fill paint
     */
    addFill(parentId, options = {}) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Fill' },
        ];
        if (options.isVisible !== undefined) {
            properties.push({ key: PropertyKey.isVisible, value: options.isVisible ? 1 : 0 });
        }
        if (options.fillRule !== undefined) {
            properties.push({ key: PropertyKey.fillRule, value: options.fillRule });
        }
        return this.addObject(ObjectType.Fill, properties, parentId);
    }
    /**
     * Add a SolidColor
     * @param color ARGB color value (e.g., 0xFF3498DB for blue)
     */
    addSolidColor(parentId, color, name) {
        const properties = [
            { key: PropertyKey.name, value: name ?? 'Color' },
            { key: PropertyKey.colorValue, value: color },
        ];
        return this.addObject(ObjectType.SolidColor, properties, parentId);
    }
    /**
     * Add a Stroke paint
     */
    addStroke(parentId, options = {}) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Stroke' },
        ];
        if (options.thickness !== undefined) {
            properties.push({ key: PropertyKey.thickness, value: options.thickness });
        }
        if (options.cap !== undefined) {
            properties.push({ key: PropertyKey.cap, value: options.cap });
        }
        if (options.join !== undefined) {
            properties.push({ key: PropertyKey.join, value: options.join });
        }
        return this.addObject(ObjectType.Stroke, properties, parentId);
    }
    /**
     * Add a Node (group/transform container)
     * Nodes can contain other nodes or shapes, and apply transforms
     */
    addNode(parentId, options = {}) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Node' },
        ];
        if (options.x !== undefined) {
            properties.push({ key: PropertyKey.x, value: options.x });
        }
        if (options.y !== undefined) {
            properties.push({ key: PropertyKey.y, value: options.y });
        }
        if (options.rotation !== undefined) {
            properties.push({ key: PropertyKey.rotation, value: options.rotation });
        }
        if (options.scaleX !== undefined) {
            properties.push({ key: PropertyKey.scaleX, value: options.scaleX });
        }
        if (options.scaleY !== undefined) {
            properties.push({ key: PropertyKey.scaleY, value: options.scaleY });
        }
        return this.addObject(ObjectType.Node, properties, parentId);
    }
    /**
     * Add a PointsPath (custom vector path made of vertices)
     * Add vertices as children using addVertex() or addCubicVertex()
     */
    addPointsPath(parentId, options = {}) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Path' },
        ];
        if (options.closed !== undefined) {
            properties.push({ key: PropertyKey.isClosed, value: options.closed ? 1 : 0 });
        }
        return this.addObject(ObjectType.PointsPath, properties, parentId);
    }
    /**
     * Add a StraightVertex (straight line point in a path)
     */
    addVertex(parentId, options) {
        const properties = [
            { key: PropertyKey.vertexX, value: options.x },
            { key: PropertyKey.vertexY, value: options.y },
        ];
        if (options.name !== undefined) {
            properties.unshift({ key: PropertyKey.name, value: options.name });
        }
        return this.addObject(ObjectType.StraightVertex, properties, parentId);
    }
    /**
     * Add a CubicVertex (bezier curve point with control handles)
     * inX/inY: incoming control point (from previous vertex)
     * outX/outY: outgoing control point (to next vertex)
     */
    addCubicVertex(parentId, options) {
        const properties = [
            { key: PropertyKey.vertexX, value: options.x },
            { key: PropertyKey.vertexY, value: options.y },
            { key: PropertyKey.inX, value: options.inX },
            { key: PropertyKey.inY, value: options.inY },
            { key: PropertyKey.outX, value: options.outX },
            { key: PropertyKey.outY, value: options.outY },
        ];
        if (options.name !== undefined) {
            properties.unshift({ key: PropertyKey.name, value: options.name });
        }
        return this.addObject(ObjectType.CubicVertex, properties, parentId);
    }
    /**
     * Add a LinearGradient (gradient fill/stroke color)
     * Coordinates are relative to the shape
     */
    addLinearGradient(parentId, options) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Gradient' },
            { key: PropertyKey.startX, value: options.startX },
            { key: PropertyKey.startY, value: options.startY },
            { key: PropertyKey.endX, value: options.endX },
            { key: PropertyKey.endY, value: options.endY },
        ];
        if (options.opacity !== undefined) {
            properties.push({ key: PropertyKey.opacity, value: options.opacity });
        }
        return this.addObject(ObjectType.LinearGradient, properties, parentId);
    }
    /**
     * Add a RadialGradient
     */
    addRadialGradient(parentId, options) {
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'RadialGradient' },
            { key: PropertyKey.startX, value: options.startX },
            { key: PropertyKey.startY, value: options.startY },
            { key: PropertyKey.endX, value: options.endX },
            { key: PropertyKey.endY, value: options.endY },
        ];
        if (options.opacity !== undefined) {
            properties.push({ key: PropertyKey.opacity, value: options.opacity });
        }
        return this.addObject(ObjectType.RadialGradient, properties, parentId);
    }
    /**
     * Add a GradientStop (color stop in a gradient)
     * @param position 0.0 to 1.0 position along the gradient
     * @param color ARGB color value
     */
    addGradientStop(parentId, options) {
        const properties = [
            { key: PropertyKey.stopPosition, value: options.position },
            { key: PropertyKey.stopColor, value: options.color },
        ];
        if (options.name !== undefined) {
            properties.unshift({ key: PropertyKey.name, value: options.name });
        }
        return this.addObject(ObjectType.GradientStop, properties, parentId);
    }
    /**
     * Add a LinearAnimation
     * @param artboardId The artboard this animation belongs to
     * @param options Animation options
     * @returns The animation's object ID
     */
    addLinearAnimation(artboardId, options) {
        const loopValues = { oneShot: 0, loop: 1, pingPong: 2 };
        const properties = [
            { key: PropertyKey.name, value: options.name ?? 'Animation' },
            { key: PropertyKey.fps, value: options.fps ?? 60 },
            { key: PropertyKey.duration, value: options.duration },
            { key: PropertyKey.speed, value: options.speed ?? 1 },
            { key: PropertyKey.loopValue, value: loopValues[options.loop ?? 'loop'] },
        ];
        return this.addObject(ObjectType.LinearAnimation, properties, artboardId);
    }
    /**
     * Add a KeyedObject (links animation to a target object)
     * @param animationId The animation this keyed object belongs to
     * @param targetObjectId The object being animated (e.g., Shape)
     */
    addKeyedObject(animationId, targetObjectId) {
        const properties = [
            { key: PropertyKey.objectId, value: targetObjectId },
        ];
        return this.addObject(ObjectType.KeyedObject, properties, animationId);
    }
    /**
     * Add a KeyedProperty (specifies which property to animate)
     * @param keyedObjectId The keyed object this property belongs to
     * @param propertyKey The property to animate (e.g., PropertyKey.x, PropertyKey.y)
     */
    addKeyedProperty(keyedObjectId, propertyKey) {
        const properties = [
            { key: PropertyKey.propertyKeyId, value: propertyKey },
        ];
        return this.addObject(ObjectType.KeyedProperty, properties, keyedObjectId);
    }
    /**
     * Add a KeyFrameDouble (a keyframe with a float value)
     * @param keyedPropertyId The keyed property this keyframe belongs to
     * @param options Keyframe options
     */
    addKeyFrameDouble(keyedPropertyId, options) {
        const interpolationTypes = { hold: 0, linear: 1, cubic: 2 };
        const properties = [
            { key: PropertyKey.frame, value: options.frame },
            { key: PropertyKey.keyFrameValue, value: options.value },
            { key: PropertyKey.interpolationType, value: interpolationTypes[options.interpolation ?? 'linear'] },
        ];
        return this.addObject(ObjectType.KeyFrameDouble, properties, keyedPropertyId);
    }
    /**
     * Export to .riv binary format
     */
    export() {
        const writer = new BinaryWriter();
        // 1. Fingerprint "RIVE"
        for (const char of RIVE_FINGERPRINT) {
            writer.writeByte(char.charCodeAt(0));
        }
        // 2. Version
        writer.writeVarUint(MAJOR_VERSION);
        writer.writeVarUint(MINOR_VERSION);
        // 3. File ID (0 for generated files)
        writer.writeVarUint(0);
        // 4. Property keys (Table of Contents)
        // ToC is for extension properties that the runtime doesn't know about.
        // Core properties (including gradient coords) are built into the runtime.
        // We only need property 160 as a marker.
        writer.writeVarUint(160); // Property key
        writer.writeVarUint(0); // End of property keys
        // 5. Field types (2 bits per property, packed into uint32)
        // Property 160 uses VarUint (0)
        writer.writeUint32(0);
        // Find artboard indices (for calculating relative parentIds)
        const artboardIndices = [];
        for (let i = 0; i < this.objects.length; i++) {
            if (this.objects[i].type === ObjectType.Artboard) {
                artboardIndices.push(i);
            }
        }
        // Calculate relative parentIds for each object
        // Rive's parentId encoding:
        // 1. Direct artboard children: parentId = 0
        // 2. Children of direct artboard children: distance to parent, siblings share
        // 3. Deeper objects: distance to the "root" ancestor (first non-artboard ancestor)
        const relativeParentIds = new Map();
        // Helper to find the root ancestor (direct child of artboard)
        const findRootAncestor = (idx) => {
            let current = idx;
            while (current !== undefined) {
                const ancestorParent = this.objects[current].absoluteParentId;
                if (ancestorParent !== undefined && artboardIndices.includes(ancestorParent)) {
                    return current;
                }
                current = ancestorParent;
            }
            return undefined;
        };
        for (let i = 0; i < this.objects.length; i++) {
            const obj = this.objects[i];
            if (obj.absoluteParentId === undefined)
                continue;
            const parentId = obj.absoluteParentId;
            // If parent is artboard, use 0
            if (artboardIndices.includes(parentId)) {
                relativeParentIds.set(i, 0);
                continue;
            }
            // Check if parent is a direct child of artboard
            const parentObj = this.objects[parentId];
            const grandparentId = parentObj?.absoluteParentId;
            if (grandparentId !== undefined && artboardIndices.includes(grandparentId)) {
                // Parent is direct child of artboard - use distance to parent with sibling handling
                const firstChildIdx = this.firstChildIndex.get(parentId);
                if (firstChildIdx !== undefined && firstChildIdx < i && relativeParentIds.has(firstChildIdx)) {
                    relativeParentIds.set(i, relativeParentIds.get(firstChildIdx));
                }
                else {
                    relativeParentIds.set(i, i - parentId);
                }
            }
            else {
                // Deeper object - use distance to root ancestor (e.g., Shape)
                // Siblings share the same parentId
                const rootAncestor = findRootAncestor(i);
                if (rootAncestor !== undefined) {
                    const firstChildIdx = this.firstChildIndex.get(parentId);
                    if (firstChildIdx !== undefined && firstChildIdx < i && relativeParentIds.has(firstChildIdx)) {
                        relativeParentIds.set(i, relativeParentIds.get(firstChildIdx));
                    }
                    else {
                        relativeParentIds.set(i, i - rootAncestor);
                    }
                }
                else {
                    relativeParentIds.set(i, i - parentId);
                }
            }
        }
        // 6. Objects
        for (let objIndex = 0; objIndex < this.objects.length; objIndex++) {
            const obj = this.objects[objIndex];
            // Object type
            writer.writeVarUint(obj.type);
            // Write name property first (if present)
            const nameProperty = obj.properties.find((p) => p.key === PropertyKey.name);
            if (nameProperty) {
                writer.writeVarUint(PropertyKey.name);
                writer.writeString(String(nameProperty.value));
            }
            // Write parentId after name
            if (obj.absoluteParentId !== undefined) {
                writer.writeVarUint(PropertyKey.parentId);
                const relativeId = relativeParentIds.get(objIndex) ?? 0;
                writer.writeVarUint(relativeId);
            }
            // Write remaining properties (skip name since we already wrote it)
            for (const prop of obj.properties) {
                if (prop.key === PropertyKey.name)
                    continue; // Already written
                writer.writeVarUint(prop.key);
                const fieldType = PropertyFieldType[prop.key] ?? FieldType.Float;
                switch (fieldType) {
                    case FieldType.VarUint:
                        writer.writeVarUint(typeof prop.value === 'boolean' ? (prop.value ? 1 : 0) : Number(prop.value));
                        break;
                    case FieldType.String:
                        writer.writeString(String(prop.value));
                        break;
                    case FieldType.Float:
                        writer.writeFloat(Number(prop.value));
                        break;
                    case FieldType.Color:
                        writer.writeColor(Number(prop.value));
                        break;
                }
            }
            // Terminate object properties
            writer.writeVarUint(0);
        }
        return writer.toUint8Array();
    }
}
/**
 * Helper to create ARGB color from components
 */
export function rgba(r, g, b, a = 255) {
    return ((a & 0xff) << 24) | ((r & 0xff) << 16) | ((g & 0xff) << 8) | (b & 0xff);
}
/**
 * Helper to create ARGB color from hex string
 */
export function hex(color) {
    const clean = color.replace('#', '');
    if (clean.length === 6) {
        return 0xff000000 | parseInt(clean, 16);
    }
    else if (clean.length === 8) {
        // RRGGBBAA -> AARRGGBB
        const rrggbb = parseInt(clean.slice(0, 6), 16);
        const aa = parseInt(clean.slice(6, 8), 16);
        return (aa << 24) | rrggbb;
    }
    throw new Error(`Invalid hex color: ${color}`);
}
